public int findMaxSubsequenceLength(int[] A, int N, int D) {
    int maxLength = 0;
    for (int i = 0; i < N; i++) {
        int currentLength = 1;
        for (int j = i + 1; j < N; j++) {
            if (Math.abs(A[j] - A[j - 1]) <= D) {
                currentLength++;
            } else {
                break;
            }
        }
        maxLength = Math.max(maxLength, currentLength);
    }
    return maxLength;
}
